package com.apartment.service;
import java.math.BigDecimal; import java.sql.*; import java.util.UUID;
public class PaymentService { private final Connection c; public PaymentService(Connection c){this.c=c;} public void pay(long chargeId,BigDecimal amount)throws SQLException{c.setAutoCommit(false);try{BigDecimal total,charge;try(var p=c.prepareStatement("SELECT amount FROM maintenance_charge WHERE charge_id=? FOR UPDATE")){p.setLong(1,chargeId);try(var rs=p.executeQuery()){if(!rs.next())throw new SQLException("Charge not found");charge=rs.getBigDecimal(1);}} try(var p=c.prepareStatement("SELECT COALESCE(SUM(amount_paid),0) FROM payment WHERE charge_id=?")){p.setLong(1,chargeId);try(var rs=p.executeQuery()){rs.next();total=rs.getBigDecimal(1);}}if(amount.signum()<=0||total.add(amount).compareTo(charge)>0)throw new SQLException("Invalid or excess payment");try(var p=c.prepareStatement("INSERT INTO payment(charge_id,amount_paid,reference_no) VALUES(?,?,?)")){p.setLong(1,chargeId);p.setBigDecimal(2,amount);p.setString(3,"JAVA-"+UUID.randomUUID());p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();if(e instanceof SQLException se)throw se;throw new SQLException(e);}finally{c.setAutoCommit(true);}} }
